import handler from "./.open-next/worker.js";
import { processDuePushNotifications } from "./lib/server/push-delivery";
import { ensureAutomaticReminders } from "./lib/server/automatic-reminders";
import { processDueReminderEmails } from "./lib/server/reminder-email-delivery";
import { reconcileR2Materials } from "./lib/server/materials-r2-sync";

type ScheduledContext = {
  waitUntil(promise: Promise<unknown>): void;
};

function runScheduledJob(
  label: string,
  job: () => Promise<unknown>,
) {
  return job()
    .then((result) => console.info(label, result))
    .catch((error) => {
      console.error(`${label}-failed`, error);
    });
}

const worker = {
  fetch: handler.fetch,

  scheduled(
    _controller: unknown,
    env: CloudflareEnv,
    ctx: ScheduledContext,
  ) {
    ctx.waitUntil(processScheduledJobs(env));
  },
};

export async function processScheduledJobs(env: CloudflareEnv) {
  // Reconcile first so notifications due in this invocation are visible to
  // both delivery channels. A channel failure still does not block the other.
  const automaticReminders = await runScheduledJob(
    "automatic-reminders",
    () => ensureAutomaticReminders(env),
  );
  const pushDelivery = await runScheduledJob(
    "push-delivery",
    () => processDuePushNotifications(env),
  );
  const reminderEmailDelivery = await runScheduledJob(
    "reminder-email-delivery",
    () => processDueReminderEmails(env),
  );
  const materialCatalog = await runScheduledJob(
    "r2-material-catalog",
    () => reconcileR2Materials(env.DB, env.MATERIALS_BUCKET),
  );
  return { automaticReminders, pushDelivery, reminderEmailDelivery, materialCatalog };
}

export default worker;

